        .iter()
        .filter_map(|row| {
            Some(Allocated {
                number: row.number(key)?,
                variant: rule(row.status()).then(|| {
                    generated_name(row.field(named_by).unwrap_or_else(|| {
                        panic!("a {table} row numbered by {key} has no {named_by}")
                    }))
                }),
            })
        })
        .collect()
