/// line opens a block and every `key = value` line until the next heading
/// belongs to it. Not a TOML crate, for the reason `admission.rs` gives.
fn tables() -> Vec<Table> {
    let mut out: Vec<Table> = Vec::new();
    for line in REGISTRY.lines() {
