            continue;
        }
        if line.starts_with('[') {
            out.push(Table {
                name: line.trim_matches(|c| c == '[' || c == ']').to_owned(),
                fields: Vec::new(),
            });
            continue;
        }
        if let (Some(last), Some((key, value))) = (out.last_mut(), line.split_once('=')) {
